// A small, dependency-free markdown renderer for the story show page. It covers
// the subset that actually appears in reviews, story files, and post-PR notes:
// ATX headers, fenced code, bullet/ordered lists, blockquotes, horizontal
// rules, paragraphs, and inline code/bold/italic/links. It is intentionally not
// a full CommonMark implementation — the project is stdlib-only by design, and
// this keeps it that way. All text is HTML-escaped; only the tags we emit are
// trusted, so the result is safe to inject as template.HTML.

var (
	mdHeaderRE  = regexp.MustCompile(`^(#{1,6})\s+(.*?)\s*#*$`)
	mdBulletRE  = regexp.MustCompile(`^[ \t]*[-*+]\s+(.*)$`)
	mdOrderedRE = regexp.MustCompile(`^[ \t]*\d+\.\s+(.*)$`)
	mdLinkRE    = regexp.MustCompile(`\[([^\]]+)\]\(([^)\s]+)\)`)
	// mdWikiRE matches cross-story links: [[story-id]] or [[story-id|label]].
	mdWikiRE = regexp.MustCompile(`\[\[([^\]|]+)(?:\|([^\]]+))?\]\]`)
	mdBoldRE    = regexp.MustCompile(`\*\*([^*]+?)\*\*`)
	mdItalicRE  = regexp.MustCompile(`\*([^*\s][^*]*?)\*`)
	// mdTableSepRE matches a GFM table delimiter row: pipe-separated runs of
	// dashes with optional alignment colons, e.g. "| :--- | ---: | :--: |".
	mdTableSepRE = regexp.MustCompile(`^\s*\|?\s*:?-+:?\s*(\|\s*:?-+:?\s*)*\|?\s*$`)
)

// RenderMarkdown converts markdown source to safe HTML.
func RenderMarkdown(src string) template.HTML {
	lines := strings.Split(strings.ReplaceAll(src, "\r\n", "\n"), "\n")
	var b strings.Builder
	i := 0
	for i < len(lines) {
		line := lines[i]
		trimmed := strings.TrimSpace(line)

		switch {
		case trimmed == "":
			i++

		case strings.HasPrefix(trimmed, "```") || strings.HasPrefix(trimmed, "~~~"):
			fence := trimmed[:3]
			i++
			var code []string
			for i < len(lines) && !strings.HasPrefix(strings.TrimSpace(lines[i]), fence) {
				code = append(code, lines[i])
				i++
			}
			i++ // consume closing fence (no-op past EOF)
			b.WriteString("<pre><code>")
			b.WriteString(html.EscapeString(strings.Join(code, "\n")))
			b.WriteString("</code></pre>")

		case strings.HasPrefix(trimmed, "<!--"):
			// HTML comment (e.g. the "<!-- comments: N -->" review sentinel):
			// skip it entirely, across lines until the closing marker.
			for i < len(lines) && !strings.Contains(lines[i], "-->") {
				i++
			}
			i++

		case mdHeaderRE.MatchString(line):
			m := mdHeaderRE.FindStringSubmatch(line)
			n := len(m[1])
			fmt.Fprintf(&b, "<h%d>%s</h%d>", n, renderInline(m[2]), n)
			i++

		case trimmed == "---" || trimmed == "***" || trimmed == "___":
			b.WriteString("<hr>")
			i++

		case strings.HasPrefix(trimmed, ">"):
			var quote []string
			for i < len(lines) && strings.HasPrefix(strings.TrimSpace(lines[i]), ">") {
				q := strings.TrimSpace(strings.TrimSpace(lines[i])[1:])
				quote = append(quote, q)
				i++
			}
			b.WriteString("<blockquote>")
			b.WriteString(renderInline(strings.Join(quote, " ")))
			b.WriteString("</blockquote>")

		case mdBulletRE.MatchString(line) || mdOrderedRE.MatchString(line):
			ordered := mdOrderedRE.MatchString(line)
			tag := "ul"
			if ordered {
				tag = "ol"
			}
			fmt.Fprintf(&b, "<%s>", tag)
			for i < len(lines) {
				re := mdBulletRE
				if ordered {
					re = mdOrderedRE
				}
				m := re.FindStringSubmatch(lines[i])
				if m == nil {
					break
				}
				b.WriteString("<li>")
				b.WriteString(renderInline(m[1]))
				b.WriteString("</li>")
				i++
			}
			fmt.Fprintf(&b, "</%s>", tag)

		// GFM table: a header row containing a pipe immediately followed by a
		// delimiter row of dashes/colons. Both this page's stories and RFCs use
		// them, and they otherwise render as raw "| a | b |" text.
		case strings.Contains(line, "|") && i+1 < len(lines) && mdTableSepRE.MatchString(lines[i+1]):
			headers := splitTableRow(line)
			aligns := tableAligns(lines[i+1], len(headers))
			i += 2
			var rows [][]string
			for i < len(lines) && strings.TrimSpace(lines[i]) != "" && strings.Contains(lines[i], "|") {
				rows = append(rows, splitTableRow(lines[i]))
				i++
			}
			b.WriteString("<table><thead><tr>")
			for c, h := range headers {
				fmt.Fprintf(&b, "<th%s>%s</th>", alignAttr(aligns, c), renderInline(h))
			}
			b.WriteString("</tr></thead><tbody>")
			for _, row := range rows {
				b.WriteString("<tr>")
				for c := range headers {
					cell := ""
					if c < len(row) {
						cell = row[c]
					}
					fmt.Fprintf(&b, "<td%s>%s</td>", alignAttr(aligns, c), renderInline(cell))
				}
				b.WriteString("</tr>")
			}
			b.WriteString("</tbody></table>")

		default:
			var para []string
			for i < len(lines) {
				if strings.TrimSpace(lines[i]) == "" || mdIsBlockStart(lines[i]) {
					break
				}
				para = append(para, lines[i])
				i++
			}
			b.WriteString("<p>")
			b.WriteString(renderInline(strings.Join(para, " ")))
			b.WriteString("</p>")
		}
	}
	return template.HTML(b.String())
}

// mdIsBlockStart reports whether a line begins a non-paragraph block, so
// paragraph accumulation stops before swallowing it.
func mdIsBlockStart(line string) bool {
	t := strings.TrimSpace(line)
	switch {
	case strings.HasPrefix(t, "```"), strings.HasPrefix(t, "~~~"),
		strings.HasPrefix(t, "<!--"), strings.HasPrefix(t, ">"),
		t == "---", t == "***", t == "___":
		return true
	}
	return mdHeaderRE.MatchString(line) || mdBulletRE.MatchString(line) || mdOrderedRE.MatchString(line)
}

// splitTableRow splits a GFM table row into trimmed cells, dropping the
// optional leading/trailing pipes. It does not handle escaped pipes inside
// cells — rare in these docs and not worth the complexity here.
func splitTableRow(line string) []string {
	s := strings.TrimSpace(line)
	s = strings.TrimPrefix(s, "|")
	s = strings.TrimSuffix(s, "|")
	parts := strings.Split(s, "|")
	cells := make([]string, len(parts))
	for i, p := range parts {
		cells[i] = strings.TrimSpace(p)
	}
	return cells
}

// tableAligns reads per-column alignment from a delimiter row: leading colon =
// left, trailing = right, both = center, neither = default (empty).
func tableAligns(sep string, n int) []string {
	cells := splitTableRow(sep)
	out := make([]string, n)
	for i := 0; i < n && i < len(cells); i++ {
		c := cells[i]
		left := strings.HasPrefix(c, ":")
		right := strings.HasSuffix(c, ":")
		switch {
		case left && right:
			out[i] = "center"
		case right:
			out[i] = "right"
		case left:
			out[i] = "left"
		}
	}
	return out
}

// alignAttr renders the style attribute for a table cell's column alignment.
func alignAttr(aligns []string, c int) string {
	if c < len(aligns) && aligns[c] != "" {
		return ` style="text-align:` + aligns[c] + `"`
	}
	return ""
}

// renderInline renders inline markdown. Code spans are handled first and their
// contents left verbatim (escaped, no further markup), so emphasis markers
// inside `code` are not interpreted.
func renderInline(s string) string {
	var b strings.Builder
	for {
		i := strings.IndexByte(s, '`')
		if i < 0 {
			b.WriteString(renderInlineText(s))
			break
		}
		j := strings.IndexByte(s[i+1:], '`')
		if j < 0 {
			b.WriteString(renderInlineText(s))
			break
		}
		b.WriteString(renderInlineText(s[:i]))
		b.WriteString("<code>")
		b.WriteString(html.EscapeString(s[i+1 : i+1+j]))
		b.WriteString("</code>")
		s = s[i+1+j+1:]
	}
	return b.String()
}

// renderInlineText escapes text then applies links and emphasis. Markdown
// syntax characters ([](), *) survive HTML escaping, so escaping first is safe.
// Underscore emphasis is deliberately not supported — it would mangle
// snake_case identifiers and file names common in reviews.
func renderInlineText(s string) string {
	s = html.EscapeString(s)
	// Cross-story wiki links resolve to the story show page. Run before the
	// standard link pass; [[id]] has no "(" so the two regexes don't overlap.
	s = mdWikiRE.ReplaceAllStringFunc(s, func(m string) string {
		sub := mdWikiRE.FindStringSubmatch(m)
		id := strings.TrimSpace(html.UnescapeString(sub[1]))
		label := sub[2]
		if strings.TrimSpace(label) == "" {
			label = sub[1]
		}
		return `<a href="/story/` + url.PathEscape(id) + `">` + label + `</a>`
	})
	s = mdLinkRE.ReplaceAllStringFunc(s, func(m string) string {
		sub := mdLinkRE.FindStringSubmatch(m)
		text, url := sub[1], sub[2]
		if !mdSafeURL(html.UnescapeString(url)) {
			return m
		}
		return `<a href="` + url + `" target="_blank" rel="noopener">` + text + `</a>`
	})
	s = mdBoldRE.ReplaceAllString(s, "<strong>$1</strong>")
	s = mdItalicRE.ReplaceAllString(s, "<em>$1</em>")
	return s
}

// mdSafeURL allows only link targets that can't execute script.
func mdSafeURL(u string) bool {
	l := strings.ToLower(strings.TrimSpace(u))
	return strings.HasPrefix(l, "http://") || strings.HasPrefix(l, "https://") ||
		strings.HasPrefix(l, "mailto:") || strings.HasPrefix(l, "/") || strings.HasPrefix(l, "#")
}
